import std.concurrent as conc

pub type AppError = Failed(String)

fn touch(h: conc.Mutex<Int64>, v: Int64) -> Int64 {
    let out = h.get()
    return v + out
}

pub fn main() -> Result<(), AppError> {
    let m = conc.Mutex(0)
    let r = m.update(|v| touch(m, v))
    let _ = r
    return Ok(())
}
